import pandas as pd 
from datetime import datetime 

def log_results(results: dict, lakehouse_abfs: str)-> None:
    """Logs the validation results to a DQ Validation Results Lakehouse table (at the given lakehouse_abfs path)

    Inputs: 
        results: dict - the results dictionary returned from a GX validation. 
        lakehouse_abfs: str - the ABFSS path of the DQ Validation Results Lakehouse Table 

    """
    
    # constuct your flattened results
    results_flattened = [
        {
            "validation_id": results.meta['validation_id'], 
            "success": result.success, 
            "test_timestamp": datetime.strptime(results.meta['batch_markers']['ge_load_time'], "%Y%m%dT%H%M%S.%fZ") 
        } for result in results.results] 

    # convert results to a pandas dataframe
    pandas_df = pd.DataFrame(results_flattened)

    # convert to spark dataframe 
    spark_results_df = spark.createDataFrame(pandas_df)
    
    # append this dataframe to the Lakehouse Table 
    spark_results_df.write.mode("append").save(lakehouse_abfs)


def move_file(passed: bool, results: dict) -> None:
    """Moves the incoming file, after validation, using notebookutils.  
    Can move either to the 'success' folder, if the validation is successful, 
    or to the quaratine folder for further investigation. 
    All 

    Inputs: 
        passed: bool - the validation result boolean
        results: dict - GX validation results dictionary
    """
    # get the from_path from the 
    from_path = results.meta['batch_spec']['path'].replace("/lakehouse/default/", "")

    # extract the timestamp of the validation, and reformat it to be used in the new filename    
    test_datetime = datetime.strptime(results.meta['batch_markers']['ge_load_time'], "%Y%m%dT%H%M%S.%fZ") 
    test_dt_formatted = test_datetime.strftime("%Y%m%dT%H%M")

    # new filename is the timestamp (formatted) and the previous filename 
    file_name = f"{test_dt_formatted}_{results.meta['active_batch_definition']['batch_identifiers']['path']}"
    
    to_path = ""

    if passed == True: 
        to_path = f"Files/success/{file_name}"

    elif passed == False: 
        to_path = f"Files/quarantine/{file_name}"

    notebookutils.fs.mv(from_path, to_path, True, True)



