from pyspark.sql.functions import current_timestamp
import notebookutils

if results.success == True: 
    # get the relative file path (without /lakehouse/default/)
    path = results.meta['batch_spec']['path'].replace("/lakehouse/default/", "")

    # read the CSV into a Spark DF
    df = spark.read.format('csv').option("header", "true").load(path)

    # add a raw loading timestamp 
    df = df.withColumn("RawLoad_TS", current_timestamp())
    
    # append it to raw_sales
    df.write.mode("append").saveAsTable("raw_sales")

    # move the file to the Files/success folder 
    move_file(passed=True, results=results) 
    
else: 

    # move the file to the Files/quarantine folder 
    move_file(passed=False, results=results) 


#run the 
log_results(results, dq_validation_logging_table_abfss) 

 

